-- Gen 3 cloud deck: precomputed density field + first-use timing (Lab 60, fixes60 item 2).
--
-- Why: Clouds.image() in compat/CloudsSource.lua builds a 512x512 fBm field in pure Lua
-- (about 10 million noise samples). On the Quest (LuaJIT, JIT off) that was 4.27 s inside the
-- first outdoor eye frame. The field is deterministic procedural noise, our own data, so it
-- ships as raw RGBA8 bytes generated by the EXACT same Clouds.image() code and is loaded here
-- with one memcpy-style love.image.newImageData call.
--
-- What this file does NOT do: it never edits compat/CloudsSource.lua or lib/. It replaces ONE
-- function value on the deck instance (deck.clouds.image) and only when every check passes;
-- any failure (missing/short/corrupt asset, hash mismatch, a changed generator or constants,
-- a missing love API) leaves the stock generator in place and logs the reason once.
-- Gen3SkyRse.lua loads this and calls it only while VRITK_FRLG_HOST is installed.
--
-- Same look: the stock code ends with love.graphics.newImage(imageData); img:setFilter(
-- "nearest","nearest"); img:setWrap("repeat","repeat") and nothing else (no mipmaps, no
-- settings table). makeImage() does exactly that. tools/cloudgen verifies pixel hashes.
--
-- Reproduce from the pinned stock Clouds.image() generator. The metadata below
-- identifies both the exact procedural field and its normalized source recipe.
local mod, loadModule, hostLib, shared = ...
local Asset = {}

-- BEGIN ASSET META (written by tools/make_cloud_asset.py; do not edit by hand)
Asset.PATH = 'compat/gen3/assets/cloud_field_512.rgba8'
Asset.W, Asset.H = 512, 512
Asset.BYTES = 1048576
Asset.SHA256 = '240d6714c99064f27531e4f73cbc7ed0c9a236d0841ce09c03e07d7325f93c2f'
Asset.SRC_SHA256 = 'b7aacaade9a5a81734a5694a89304a01d605e4dd9e760dbd2ed07764e0cc5391'
Asset.PARAMS = 'TEX=512;SEED=1337;EVOLVE_SEED_A=7331;EVOLVE_SEED_B=9317;VARIANTS=4;COVERAGE=0.3;SOFTNESS=0.28;STEPS=4'
-- END ASSET META

Asset.SRC_PATH = 'compat/CloudsSource.lua'

local function nowDefault() return love.timer.getTime() end

local function hexSha256(bytes)
  local d = love and love.data
  if not (d and d.hash and d.encode) then return nil end
  local ok, raw = pcall(d.hash, 'sha256', bytes)
  if not ok or type(raw) ~= 'string' then return nil end
  local ok2, hex = pcall(d.encode, 'string', 'hex', raw)
  if not ok2 then return nil end
  return tostring(hex)
end
Asset.hexSha256 = hexSha256

-- The generator constants the asset depends on, as one string.
function Asset.paramsOf(c)
  return ('TEX=%s;SEED=%s;EVOLVE_SEED_A=%s;EVOLVE_SEED_B=%s;VARIANTS=%s;COVERAGE=%s;SOFTNESS=%s;STEPS=%s'):format(
    tostring(c.TEX), tostring(c.SEED), tostring(c.EVOLVE_SEED_A), tostring(c.EVOLVE_SEED_B),
    tostring(c.VARIANTS), tostring(c.COVERAGE), tostring(c.SOFTNESS), tostring(c.STEPS))
end

-- Source text with line endings normalised (a CRLF checkout must not invalidate the asset).
function Asset.normalisedSourceHash(src)
  return hexSha256((src:gsub('\r\n', '\n')))
end

-- readFn(path) -> bytes|nil. Returns ImageData or nil, reason.
function Asset.readData(readFn)
  local okR, bytes = pcall(readFn, Asset.PATH)
  if not okR or type(bytes) ~= 'string' then return nil, 'asset missing' end
  if #bytes ~= Asset.BYTES then return nil, 'asset size ' .. #bytes .. ' ~= ' .. Asset.BYTES end
  local hex = hexSha256(bytes)
  if hex == nil then return nil, 'sha256 unavailable' end
  if hex ~= Asset.SHA256 then return nil, 'asset hash mismatch' end
  local okD, data = pcall(love.image.newImageData, Asset.W, Asset.H, 'rgba8', bytes)
  if not okD or not data then return nil, 'newImageData: ' .. tostring(data) end
  return data
end

-- The stock tail of Clouds.image(), verbatim in effect.
function Asset.makeImage(data)
  local img = love.graphics.newImage(data)
  img:setFilter('nearest', 'nearest')
  img:setWrap('repeat', 'repeat')
  return img
end

-- Checks that the generator on this deck is the one the asset was made from.
function Asset.validateGenerator(clouds, readFn)
  if type(clouds) ~= 'table' or type(clouds.image) ~= 'function' then return false, 'no clouds table' end
  local p = Asset.paramsOf(clouds)
  if p ~= Asset.PARAMS then return false, 'generator constants changed (' .. p .. ')' end
  local okS, src = pcall(readFn, Asset.SRC_PATH)
  if not okS or type(src) ~= 'string' then return false, 'generator source unreadable' end
  local h = Asset.normalisedSourceHash(src)
  if h == nil then return false, 'sha256 unavailable' end
  if h ~= Asset.SRC_SHA256 then return false, 'generator source changed' end
  return true
end

-- ---------------------------------------------------------------------------------------
-- attach(deck, opts): opts.log(fmt, ...), opts.now(), opts.read(path), opts.stage (table).
-- Installs, on this deck only:
--   deck.clouds.image  -> asset loader (falls back to the stock function)
--   deck.clouds.mesh   -> timed once, then the stock function is put back
--   deck.draw          -> timed once (first draw), then the stock function is put back
-- and logs 'cloud deck: new X ms, image Y ms, mesh Z ms, first draw W ms (shader create V ms)'.
-- Nothing here runs per frame after the first draw: every wrapper unwraps itself, and the
-- image loader is replaced by a constant-returning function after the first call.
-- Returns a state table (stage times, source, reason).
function Asset.attach(deck, opts)
  opts = opts or {}
  local log = opts.log or function() end
  local now = opts.now or nowDefault
  Asset.now = opts.now
  local readFn = opts.read
  local clouds = deck.clouds
  local st = opts.stage or {}
  st.new = st.new or 0
  st.image, st.mesh, st.draw, st.shader = 0, 0, 0, 0
  st.source = 'stock'
  st.reason = nil
  st.loggedDraw = false
  local stockImage, stockMesh, stockDraw = clouds.image, clouds.mesh, deck.draw
  st.stockImage = stockImage

  local useAsset, why = false, nil
  if opts.asset ~= false then
    local ok, v, w = pcall(Asset.validateGenerator, clouds, readFn)
    if ok and v then useAsset = true else why = ok and w or ('validate: ' .. tostring(v)) end
  else
    why = 'asset disabled'
  end
  st.reason = why

  local function stockPath(reason)
    st.source = 'stock'
    st.reason = reason
    if reason then log('gen3: cloud asset not used (%s); stock generator', tostring(reason)) end
    clouds.image = stockImage
    local t0 = now()
    local img = stockImage()
    st.image = (now() - t0) * 1000
    return img
  end

  if useAsset then
    local loaded
    clouds.image = function()
      if loaded ~= nil then return loaded or nil end
      local t0 = now()
      local okL, data, reason = pcall(Asset.readData, readFn)
      if okL and data then
        local okI, img = pcall(Asset.makeImage, data)
        if okI and img then
          loaded = img
          st.source = 'asset'
          st.image = (now() - t0) * 1000
          local final = img
          clouds.image = function() return final end -- constant from now on (no per-frame work)
          return img
        end
        reason = 'makeImage: ' .. tostring(img)
      else
        reason = okL and reason or ('readData: ' .. tostring(data))
      end
      return stockPath(reason)
    end
  else
    -- stock path, timed once
    local first = true
    clouds.image = function()
      if first then
        first = false
        local t0 = now()
        local img = stockImage()
        st.image = (now() - t0) * 1000
        clouds.image = stockImage
        return img
      end
      return stockImage()
    end
    if why then log('gen3: cloud asset not used (%s); stock generator', tostring(why)) end
  end

  clouds.mesh = function()
    local t0 = now()
    local m = stockMesh()
    st.mesh = (now() - t0) * 1000
    clouds.mesh = stockMesh
    return m
  end

  local function report(tag)
    log('cloud deck: new %.1f ms, image %.1f ms, mesh %.1f ms, first draw %.1f ms (shader create %.1f ms) image=%s%s',
      st.new, st.image, st.mesh, st.draw, st.shader, st.source, tag or '')
  end
  st.report = report

  -- First draw: timed once; newShader is wrapped for the duration of that one call only.
  deck.draw = function(self, ...)
    deck.draw = stockDraw
    local okD, r1, r2 = Asset.timedCall(st, stockDraw, self, ...)
    if not st.loggedDraw then st.loggedDraw = true; report(st.warmed and ' after-prewarm' or '') end
    if not okD then error(r1, 0) end
    return r1, r2
  end
  st.stockDraw = stockDraw
  return st
end

-- pcall(fn, ...) with the elapsed ms stored in st.draw and the time spent inside
-- love.graphics.newShader during the call stored in st.shader. newShader is wrapped only for
-- the duration of this one call and always restored. Used for the first real draw and for the
-- prewarm draw (once each), never per frame.
function Asset.timedCall(st, fn, ...)
  local now = Asset.now or nowDefault
  local g = love.graphics
  local realNew = g.newShader
  local shaderMs = 0
  g.newShader = function(...)
    local t0 = now()
    local a, b, c = realNew(...)
    shaderMs = shaderMs + (now() - t0) * 1000
    return a, b, c
  end
  local t0 = now()
  local okD, r1, r2 = pcall(fn, ...)
  st.draw = (now() - t0) * 1000
  g.newShader = realNew
  st.shader = shaderMs
  return okD, r1, r2
end

return Asset
